package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.client.gui.*;import net.minecraft.client.gui.screens.Screen;import net.minecraft.client.gui.components.Button;import net.minecraft.network.chat.Component;import java.util.*;
/** Read-only replicated state; buttons send requests, never mutate ammunition or deployment locally. */
public final class Mpl01Screen extends Screen{
 private final Mpl01Entity vehicle;private int x,y,w,h,page,rows;private final Button[] slots=new Button[4],targets=new Button[5];private final UUID[] ids=new UUID[5];private Button deploy,park,load,fire;private final List<Button> controls=new ArrayList<>();
 public Mpl01Screen(Mpl01Entity e){super(Component.literal("MPL-01 / PATRIOT CONTROL"));vehicle=e;}
 private Button button(String label,int x,int y,int width,Runnable action){var b=Button.builder(Component.literal(label),v->action.run()).bounds(x,y,width,20).build();addRenderableWidget(b);return b;}
 private void send(int action,int slot,UUID id){AddonNetwork.mpl01Action(new Mpl01Action(vehicle.getId(),action,slot,id==null?new UUID(0,0):id));}
 @Override protected void init(){w=Math.min(440,width-16);h=Math.min(306,height-16);x=(width-w)/2;y=(height-h)/2;rows=Math.max(1,Math.min(5,(h-185)/22));int gap=5,cw=(w-24-gap*3)/4;for(int i=0;i<4;i++){final int slot=i;slots[i]=button("",x+12+i*(cw+gap),y+59,cw,()->send(2,slot,null));}deploy=button("Deploy / retract",x+12,y+85,cw,()->send(0,0,null));park=button("Park brake",x+12+cw+gap,y+85,cw,()->send(1,0,null));load=button("Load selected",x+12+2*(cw+gap),y+85,cw,()->send(3,0,null));fire=button("FIRE",x+12+3*(cw+gap),y+85,cw,()->send(5,0,null));for(int i=0;i<5;i++){final int slot=i;targets[i]=button("",x+12,y+138+i*22,w-24,()->{if(ids[slot]!=null)send(4,0,ids[slot]);});}button("< Targets",x+12,y+h-53,85,()->page=Math.max(0,page-1));button("Targets >",x+102,y+h-53,85,()->page++);button("Close",x+w-97,y+h-53,85,this::onClose);tick();}
 @Override public void tick(){if(minecraft.player==null||minecraft.player.getVehicle()!=vehicle||vehicle.isRemoved()){onClose();return;}for(int i=0;i<4;i++){boolean loaded=(vehicle.ammoMask()&(1<<i))!=0;String state=loaded?(vehicle.phase()==Mpl01Entity.Phase.DEPLOYED?"READY":"LOADED"):vehicle.fired(i)?"FIRED":"EMPTY";slots[i].setMessage(Component.literal((vehicle.selectedSlot()==i?">":"")+(i+1)+" "+state));}deploy.setMessage(Component.literal(vehicle.phase()==Mpl01Entity.Phase.TRANSPORT?"Deploy":"Retract"));deploy.active=vehicle.phase()!=Mpl01Entity.Phase.RETRACTING;park.setMessage(Component.literal("Park: "+(vehicle.parked()?"ON":"OFF")));park.active=vehicle.phase()==Mpl01Entity.Phase.TRANSPORT;load.active=(vehicle.ammoMask()&(1<<vehicle.selectedSlot()))==0&&(vehicle.phase()==Mpl01Entity.Phase.TRANSPORT||vehicle.phase()==Mpl01Entity.Phase.DEPLOYED);fire.active=vehicle.phase()==Mpl01Entity.Phase.DEPLOYED&&(vehicle.ammoMask()&(1<<vehicle.selectedSlot()))!=0&&!vehicle.selectedTarget().isEmpty();var list=vehicle.contacts().getList("Entries",10);page=Math.min(Math.max(0,page),Math.max(0,(list.size()-1)/rows));for(int i=0;i<5;i++){int index=page*rows+i;ids[i]=index<list.size()?list.getCompound(index).getUUID("UUID"):null;targets[i].visible=i<rows&&index<list.size();if(index<list.size()){var n=list.getCompound(index);targets[i].setMessage(Component.literal((n.getUUID("UUID").toString().equals(vehicle.selectedTarget())?"> ":"")+minecraft.font.plainSubstrByWidth(n.getString("Name"),Math.max(40,w-140))+"  "+String.format(Locale.ROOT,"%.0f m",n.getDouble("Distance"))));}}}
 @Override public void render(GuiGraphics g,int mouseX,int mouseY,float partial){renderBackground(g);drawPanel(g,partial);super.render(g,mouseX,mouseY,partial);}
 private void drawPanel(GuiGraphics g,float partial){g.fill(x,y,x+w,y+h,0xf01b2525);g.fill(x,y,x+w,y+3,0xffb8ae72);g.drawString(font,title,x+12,y+10,0xffe4e8d9);String crew="Driver: "+(vehicle.getNthEntity(0)==null?"EMPTY":vehicle.getNthEntity(0).getName().getString())+" | Operator: "+(vehicle.getNthEntity(1)==null?"EMPTY":vehicle.getNthEntity(1).getName().getString());g.drawString(font,crew,x+12,y+25,0xffb8c9c2);g.drawString(font,vehicle.phase().name()+"  "+Math.round(vehicle.pose(partial)*100)+"% | "+font.plainSubstrByWidth(vehicle.status(),w-185),x+12,y+40,0xffffd38a);g.drawString(font,"MANUAL TARGET SELECTION / "+vehicle.contacts().getList("Entries",10).size()+" hostile contacts",x+12,y+116,0xffc8d6cd);if(vehicle.contacts().getList("Entries",10).isEmpty())g.drawString(font,"NO TARGET — own/team/unknown drones are excluded",x+12,y+143,0xffc0c6c0);g.drawString(font,"Four PM-01 slots. Load from your inventory; one missile per shot.",x+12,y+h-20,0xffa6b8af);}
 @Override public boolean isPauseScreen(){return false;}
}
